137	import java.util.List;
138	import java.util.Map;
139	
140	/**
141	 * The purchase data as received. Nothing is rejected while parsing: values of the wrong shape become null
142	 * (or 0 for installments) so that {@link CheckoutService} reports problems in the documented order.
143	 */
144	public record CheckoutRequest(
145	        String cpf,
146	        String email,
147	        List<Item> items,
148	        String zipCode,
149	        String region,
150	        String shippingMethod,
151	        boolean couponInformed,
152	        String coupon,
153	        String paymentMethod,
154	        int installments,
155	        String clubTier) {
156	
157	    public record Item(String sku, Integer quantity) {
158	    }
159	
160	    public static CheckoutRequest parse(Map<String, Object> body) {
161	        if (body == null) {
162	            body = Map.of();
163	        }
164	        Map<?, ?> customer = body.get("customer") instanceof Map<?, ?> m ? m : Map.of();
165	        List<Item> items = null;
166	        if (body.get("items") instanceof List<?> list) {
167	            items = list.stream().map(CheckoutRequest::item).toList();
168	        }
169	        return new CheckoutRequest(text(customer.get("cpf")), text(customer.get("email")), items,
170	                text(body.get("zipCode")), text(body.get("region")), text(body.get("shippingMethod")),
171	                body.get("coupon") != null, text(body.get("coupon")), text(body.get("paymentMethod")),
172	                installments(body), text(body.get("clubTier")));
173	    }
174	
175	    private static Item item(Object raw) {
176	        if (!(raw instanceof Map<?, ?> m)) {
177	            return new Item(null, null);
178	        }
179	        Integer quantity = null;
180	        if (m.get("quantity") instanceof Integer i) {
181	            quantity = i;
182	        } else if (m.get("quantity") instanceof Long l && l >= Integer.MIN_VALUE && l <= Integer.MAX_VALUE) {
183	            quantity = l.intValue();
184	        }
185	        return new Item(text(m.get("sku")), quantity);
186	    }
187	
188	    private static int installments(Map<String, Object> body) {
189	        Object raw = body.get("installments");
190	        if (raw == null) {
191	            return 1;
192	        }
193	        if (raw instanceof Integer i) {
194	            return i;
195	        }
196	        if (raw instanceof Long l && l >= Integer.MIN_VALUE && l <= Integer.MAX_VALUE) {
197	            return l.intValue();
198	        }
199	        return 0;
200	    }
201	
202	    private static String text(Object value) {
203	        return value instanceof String s ? s : null;
204	    }
205	}
