209	import java.math.RoundingMode;
210	
211	public final class Money {
212	
213	    public static final BigDecimal ZERO = new BigDecimal("0.00");
214	
215	    private Money() {
216	    }
217	
218	    /** Rounds to cents, half to even. */
219	    public static BigDecimal round(BigDecimal value) {
220	        return value.setScale(2, RoundingMode.HALF_EVEN);
221	    }
222	
223	    public static BigDecimal of(String value) {
224	        return round(new BigDecimal(value));
225	    }
226	
227	    /** value × rate, rounded to cents. */
228	    public static BigDecimal percent(BigDecimal value, BigDecimal rate) {
229	        return round(value.multiply(rate));
230	    }
231	}

