  2	
  3	import br.com.loja.pedidos.catalog.ProductRepository;
  4	import br.com.loja.pedidos.checkout.CheckoutRequest;
  5	import br.com.loja.pedidos.checkout.CheckoutService;
  6	import br.com.loja.pedidos.checkout.OrderSummary;
  7	import br.com.loja.pedidos.common.ApiException;
  8	import br.com.loja.pedidos.customer.CustomerRepository;
  9	import java.time.Clock;
 10	import java.time.Duration;
 11	import java.time.Instant;
 12	import java.time.OffsetDateTime;
 13	import java.time.temporal.ChronoUnit;
 14	import java.util.Comparator;
 15	import java.util.List;
 16	import java.util.UUID;
 17	import java.util.function.Supplier;
 18	import org.springframework.stereotype.Service;
 19	import org.springframework.transaction.support.TransactionTemplate;
 20	
 21	@Service
 22	public class OrderService {
 23	
 24	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 25	    private static final String PAYMENT_OK = "OK";
 26	
 27	    private final CheckoutService checkout;
 28	    private final OrderRepository orders;
 29	    private final ProductRepository products;
 30	    private final CustomerRepository customers;
 31	    private final List<OrderLifecycleListener> listeners;
 32	    private final TransactionTemplate tx;
 33	    private final Clock clock;
 34	
 35	    public OrderService(CheckoutService checkout, OrderRepository orders, ProductRepository products,
 36	                        CustomerRepository customers, List<OrderLifecycleListener> listeners,
 37	                        TransactionTemplate tx, Clock clock) {
 38	        this.checkout = checkout;
 39	        this.orders = orders;
 40	        this.products = products;
 41	        this.customers = customers;
 42	        this.listeners = listeners;
 43	        this.tx = tx;
 44	        this.clock = clock;
 45	    }
 46	
 47	    public OrderSummary summarize(CheckoutRequest request) {
 48	        return checkout.summarize(request);
 49	    }
 50	
 51	    public Order register(CheckoutRequest request) {
 52	        // computed before opening the transaction: it may call the carrier
 53	        OrderSummary summary = checkout.summarize(request);
 54	        List<Order.Item> items = request.items().stream()
 55	                .map(i -> new Order.Item(i.sku(), i.quantity())).toList();
 56	        Order order = new Order(UUID.randomUUID().toString(), OrderStatus.AWAITING_PAYMENT,
 57	                clock.instant().truncatedTo(ChronoUnit.SECONDS), summary, items, null);
 58	        customers.createIfAbsent(request.cpf(), request.email());
 59	        return inTransaction(() -> {
 60	            orders.insert(request.cpf(), request.email(), order);
 61	            return order;
 62	        });
 63	    }
 64	
 65	    public Order get(String id) {
 66	        return orders.find(id).orElseThrow(OrderService::notFound).order();
 67	    }
 68	
 69	    public Order confirmPayment(String id, String transactionId, String paidAt) {
 70	        PaymentResult result = inTransaction(() -> doConfirmPayment(id, transactionId, paidAt));
 71	        if (result.error() != null) {
 72	            throw result.error();
 73	        }
 74	        return result.order();
 75	    }
 76	
 77	    public Order ship(String id, String trackingCode) {
 78	        return inTransaction(() -> {
 79	            StoredOrder stored = lock(id);
 80	            if (trackingCode == null || trackingCode.isBlank()) {
 81	                throw ApiException.unprocessable("INVALID_ORDER");
 82	            }
 83	            requireTransition(stored, OrderStatus.SHIPPED);
 84	            orders.updateShipment(id, trackingCode);
 85	            StoredOrder shipped = reload(id);
 86	            listeners.forEach(l -> l.onShipped(shipped));
 87	            return shipped.order();
 88	        });
 89	    }
 90	
 91	    public Order deliver(String id) {
 92	        return inTransaction(() -> {
 93	            requireTransition(lock(id), OrderStatus.DELIVERED);
 94	            orders.updateStatus(id, OrderStatus.DELIVERED);
 95	            return reload(id).order();
 96	        });
 97	    }
 98	
 99	    public Order cancel(String id) {
100	        return inTransaction(() -> {
101	            StoredOrder stored = lock(id);
102	            requireTransition(stored, OrderStatus.CANCELLED);
103	            cancelLocked(stored);
104	            return reload(id).order();
105	        });
106	    }
107	
108	    private PaymentResult doConfirmPayment(String id, String transactionId, String paidAtText) {
109	        StoredOrder stored = lock(id);
110	        Instant paidAt = parseInstant(paidAtText);
111	        if (transactionId == null || transactionId.isBlank() || paidAt == null) {
112	            throw ApiException.unprocessable("INVALID_ORDER");
113	        }
114	        String previous = orders.findPaymentOutcome(id, transactionId).orElse(null);
115	        if (previous != null) {
116	            return PAYMENT_OK.equals(previous)
117	                    ? new PaymentResult(stored.order(), null)
118	                    : new PaymentResult(null, ApiException.conflict(previous));
119	        }
120	        requireTransition(stored, OrderStatus.PAID);
121	
122	        Order order = stored.order();
123	        if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
124	            return refuse(stored, transactionId, "ORDER_EXPIRED");
125	        }
126	        // lock in a fixed order so that concurrent payments cannot deadlock
127	        List<Order.Item> items = order.items().stream().sorted(Comparator.comparing(Order.Item::sku)).toList();
128	        boolean enough = true;
129	        for (Order.Item item : items) {
130	            enough &= products.lockStock(item.sku()) >= item.quantity();
131	        }
132	        if (!enough) {
133	            return refuse(stored, transactionId, "INSUFFICIENT_STOCK");
134	        }
135	        items.forEach(i -> products.decrementStock(i.sku(), i.quantity()));
136	        orders.updateStatus(id, OrderStatus.PAID);
137	        orders.recordPaymentOutcome(id, transactionId, PAYMENT_OK);
138	        StoredOrder paid = reload(id);
139	        listeners.forEach(l -> l.onPaid(paid));
