169	    public void insert(String cpf, String email, Order order) {
170	        OrderSummary s = order.summary();
171	        jdbc.sql("""
172	                INSERT INTO orders (id, cpf, email, status, created_at, tracking_code, products_subtotal,
173	                  coupon_discount, shipping_cost, delivery_days, insurance, payment_adjustment, final_total,
174	                  installments, installment_amount, next_purchase_credit, gift)
175	                VALUES (:id, :cpf, :email, :status, :createdAt, NULL, :subtotal, :discount, :shipping, :days,
176	                  :insurance, :adjustment, :total, :installments, :installmentAmount, :credit, :gift)
177	                """)
178	                .param("id", order.id()).param("cpf", cpf).param("email", email)
179	                .param("status", order.status().name())
180	                .param("createdAt", OffsetDateTime.ofInstant(order.createdAt(), ZoneOffset.UTC))
181	                .param("subtotal", s.productsSubtotal()).param("discount", s.couponDiscount())
182	                .param("shipping", s.shippingCost()).param("days", s.deliveryDays())
183	                .param("insurance", s.insurance()).param("adjustment", s.paymentAdjustment())
184	                .param("total", s.finalTotal()).param("installments", s.installments())
185	                .param("installmentAmount", s.installmentAmount()).param("credit", s.nextPurchaseCredit())
186	                .param("gift", s.gift()).update();
