327	    private final JdbcClient jdbc;
328	
329	    public CustomerRepository(JdbcClient jdbc) {
330	        this.jdbc = jdbc;
331	    }
332	
333	    /**
334	     * Creates the customer with zero credit when missing. Meant to run on its own (outside a larger
335	     * transaction): two instances may race, and the loser of the race simply finds the customer there.
336	     */
337	    public void createIfAbsent(String cpf, String email) {
338	        try {
339	            jdbc.sql("INSERT INTO customers (cpf, email, credit_balance) "
340	                    + "SELECT :cpf, :email, 0 WHERE NOT EXISTS (SELECT 1 FROM customers WHERE cpf = :cpf)")
341	                    .param("cpf", cpf).param("email", email).update();
342	        } catch (DuplicateKeyException e) {
343	            // created concurrently by another request
344	        }
345	    }
346	
347	    public Optional<Customer> find(String cpf) {
348	        return jdbc.sql("SELECT cpf, credit_balance FROM customers WHERE cpf = :cpf").param("cpf", cpf)
349	                .query((rs, n) -> new Customer(rs.getString("cpf"), rs.getBigDecimal("credit_balance").setScale(2)))
350	                .optional();
351	    }
352	
353	    public void addCredit(String cpf, BigDecimal amount) {
354	        jdbc.sql("UPDATE customers SET credit_balance = credit_balance + :a WHERE cpf = :cpf")
355	                .param("a", amount).param("cpf", cpf).update();
356	    }
