 86	import br.com.loja.pedidos.common.ApiException;
 87	import java.math.BigDecimal;
 88	import java.math.RoundingMode;
 89	
 90	/** Delivery priced and timed by an external carrier; the dispatch delay of the region is added on top. */
 91	public class CarrierShippingOption implements ShippingOption {
 92	
 93	    private final String code;
 94	    private final ServiceLevel level;
 95	    private final CarrierGateway carrier;
 96	
 97	    public CarrierShippingOption(String code, ServiceLevel level, CarrierGateway carrier) {
 98	        this.code = code;
 99	        this.level = level;
100	        this.carrier = carrier;
101	    }
102	
103	    @Override
104	    public String code() {
105	        return code;
106	    }
107	
108	    @Override
109	    public ShippingQuote quote(ShippingRequest request) {
110	        long grams = request.weightKg().multiply(BigDecimal.valueOf(1000)).setScale(0, RoundingMode.CEILING)
111	                .longValueExact();
112	        return switch (carrier.quote(request.zipCode(), grams, level)) {
113	            case CarrierGateway.Quoted q -> new ShippingQuote(q.price(),
114	                    (int) ((q.etaHours() + 23) / 24) + request.region().dispatchDelayDays());
115	            case CarrierGateway.NotServed n -> throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
116	            case CarrierGateway.Unavailable u -> throw new ApiException("CARRIER_UNAVAILABLE", 503);
117	        };
118	    }
119	}
