303	import br.com.loja.pedidos.common.Money;
304	import java.math.BigDecimal;
305	import java.math.MathContext;
306	import java.math.RoundingMode;
307	import org.springframework.stereotype.Component;
308	
309	@Component
310	public class CreditCardPayment implements PaymentMethod {
311	
312	    private static final int INTEREST_FREE_UP_TO = 3;
313	    private static final int MAX_INSTALLMENTS = 12;
314	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
315	
316	    @Override
317	    public String code() {
318	        return "CREDIT_CARD";
319	    }
320	
321	    @Override
322	    public boolean allowsInstallments(int installments) {
323	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
324	    }
325	
326	    @Override
327	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
328	        BigDecimal n = BigDecimal.valueOf(installments);
329	        if (installments <= INTEREST_FREE_UP_TO) {
330	            return new PaymentCharge(orderTotal, orderTotal.divide(n, 2, RoundingMode.HALF_EVEN));
331	        }
332	        // Price table: total × i ÷ (1 − (1 + i)^−n)
333	        MathContext mc = MathContext.DECIMAL128;
334	        BigDecimal discount = BigDecimal.ONE.divide(BigDecimal.ONE.add(MONTHLY_RATE).pow(installments, mc), mc);
335	        BigDecimal installment = Money.round(orderTotal.multiply(MONTHLY_RATE)
336	                .divide(BigDecimal.ONE.subtract(discount), mc));
337	        return new PaymentCharge(installment.multiply(n), installment);
338	    }
339	}
